"use client";

import { Button } from "@/components/ui/button";
import { useCart } from "@/context/CartContext";
import { useFavorites } from "@/context/FavoritesContext";
import { cn, fixVietnameseText, formatVND, productImageUrl } from "@/lib/utils";
import type { Product } from "@/types/product";
import { Check, Eye, Heart, ShoppingBag } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useState } from "react";

export default function ProductCard({ product }: { product: Product }) {
  const { addToCart } = useCart();
  const { toggleFavorite, isFavorite } = useFavorites();
  const isLiked = isFavorite(product.id);
  const [imageError, setImageError] = useState(false);
  const [isAdding, setIsAdding] = useState(false);
  const [justAdded, setJustAdded] = useState(false);
  const imageUrl = productImageUrl(product.image);
  const category = fixVietnameseText(product.category);
  const description = fixVietnameseText(product.description);
  const stock = product.stock ?? 100;
  const isOutOfStock = stock <= 0 || product.status === "inactive";

  const handleAddToCart = async (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    if (isOutOfStock) return;
    setIsAdding(true);
    await new Promise((resolve) => setTimeout(resolve, 300));
    addToCart({ id: product.id, name: product.name, price: product.price, image: imageUrl, quantity: 1, stock });
    setIsAdding(false);
    setJustAdded(true);
    setTimeout(() => setJustAdded(false), 1800);
  };

  const handleToggleLike = (event: React.MouseEvent) => {
    event.preventDefault();
    event.stopPropagation();
    toggleFavorite(product);
  };

  return (
    <article className="group border border-[#d7bd78]/28 bg-[#0f0d0c] text-[#f8f0df] shadow-[0_22px_80px_rgba(0,0,0,0.24)] transition duration-500 hover:-translate-y-1 hover:border-[#d7bd78]/60 hover:shadow-[0_28px_100px_rgba(0,0,0,0.38)]">
      <div className="relative border-b border-[#d7bd78]/18 bg-[radial-gradient(circle_at_50%_0%,rgba(215,189,120,0.24),transparent_42%),#15110f] p-4">
        <div className="absolute left-4 top-4 z-10 border border-[#d7bd78]/35 bg-black/55 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-[#e7ce88] backdrop-blur">
          {isOutOfStock ? "Hết hàng" : stock <= 10 ? "Sắp hết" : "Còn hàng"}
        </div>
        <Button variant="ghost" size="icon" name="Like Button" className={cn("absolute right-4 top-4 z-10 rounded-none border border-[#d7bd78]/25 bg-black/45 text-[#f8f0df] backdrop-blur hover:bg-[#d7bd78] hover:text-black", isLiked && "bg-[#d7bd78] text-black")} onClick={handleToggleLike}>
          <Heart name="Like Icon" className={cn("h-4 w-4", isLiked && "fill-current")} />
        </Button>
        <Link href={`/product/${product.id}`} className="block">
          <div className="aspect-[4/5] overflow-hidden bg-[#efe7d6]">
            {!imageError ? (
              <Image src={imageUrl} alt={product.name} width={520} height={650} className={cn("h-full w-full object-cover transition duration-700 group-hover:scale-105", isOutOfStock && "opacity-60 grayscale")} onError={() => setImageError(true)} />
            ) : (
              <div className="flex h-full items-center justify-center text-sm text-[#6b5a42]">Chưa có hình ảnh</div>
            )}
          </div>
          <div className="absolute inset-4 flex items-center justify-center bg-black/0 opacity-0 transition duration-300 group-hover:bg-black/45 group-hover:opacity-100">
            <span className="inline-flex items-center gap-2 border border-[#d7bd78]/45 bg-black/70 px-4 py-2 text-xs font-semibold uppercase tracking-[0.18em] text-[#f8f0df]"><Eye className="h-4 w-4" /> Xem nhanh</span>
          </div>
        </Link>
      </div>

      <div className="space-y-3 p-5">
        <div className="text-[11px] font-semibold uppercase tracking-[0.22em] text-[#d7bd78]">{category || "Nước hoa"}</div>
        <Link href={`/product/${product.id}`}>
          <h2 className="line-clamp-2 min-h-[3.25rem] font-serif text-xl leading-7 text-[#f8f0df] transition hover:text-[#d7bd78]">{product.name}</h2>
        </Link>
        <p className="line-clamp-2 min-h-[2.75rem] text-sm leading-6 text-[#cfc4ad]/78">{description || "Hương thơm cao cấp cho bộ sưu tập cá nhân."}</p>
        <div className="flex items-center justify-between gap-3 border-t border-[#d7bd78]/18 pt-4">
          <span className="text-lg font-bold text-[#d7bd78]">{formatVND(product.price)}</span>
        </div>
        <Button className={cn("w-full rounded-none border border-[#d7bd78] py-5 text-xs font-bold uppercase tracking-[0.2em] transition-all", isOutOfStock ? "bg-[#33302b] text-[#9f9276] hover:bg-[#33302b]" : justAdded ? "bg-[#d7bd78] text-black hover:bg-[#d7bd78]" : "bg-transparent text-[#f8f0df] hover:bg-[#d7bd78] hover:text-black")} onClick={handleAddToCart} disabled={isAdding || isOutOfStock}>
          {isOutOfStock ? <><ShoppingBag className="mr-2 h-4 w-4" /> Hết hàng</> : isAdding ? "Đang thêm..." : justAdded ? <><Check className="mr-2 h-4 w-4" /> Đã thêm</> : <><ShoppingBag className="mr-2 h-4 w-4" /> Thêm vào giỏ</>}
        </Button>
      </div>
    </article>
  );
}
